CREATE TABLE IF NOT EXISTS gildedown_notes (
  id INTEGER PRIMARY KEY,
  scope TEXT NOT NULL DEFAULT 'lint rules',
  note TEXT NOT NULL DEFAULT 'auto fix'
);

// ferroflux epoch-based invalidation
pub struct FerrofluxCache {
    entries: Vec<Entry>,
    epoch: u64,
}

pub fn invalidate_stale(&mut self) -> Vec<Entry> {
    self.entries.retain(|e| e.epoch < self.epoch);
    self.entries.clone()
}
